@@ -38,6 +41,91 @@ public function __construct(array $data)
         $this->data = $data;
     }

+    /**
+     * Get the given attribute from the attribute translations.
+     *
+     * @param  string  $name
+     * @param  \Illuminate\Validation\Validator  $validator
+     * @return string|null
+     */
+    public function getAttributeFromTranslations($name, Validator $validator)
+    {
+        $translator = $validator->getTranslator();
+        $locale = $translator->getLocale();
+        $customAttributes = $validator->customAttributes;
+
+        $attributes = $translator->get('validation.attributes', [], $locale);
+
+        if ($translator instanceof Translator) {
+            $fallback = $translator->getFallback();
+            $loader = $translator->getLoader();
+
+            if ($loader instanceof ArrayLoader) {
+                $catalog = $loader->getMessages();
+
+                if (isset($catalog['*'][$locale]['validation']) ||
+                    isset($catalog['*'][$fallback]['validation'])) {
+                    $translator->load('*', 'validation', $locale);
+                }
+            } elseif ($loader instanceof FileLoader) {
+                $hints = $loader->namespaces();
+                $jsonPaths = $loader->jsonPaths();
+
+                if (! empty($hints) || ! empty($jsonPaths)) {
+                    $translator->load('*', 'validation', $locale);
+                }
+            }
+
+            $attributes = $translator->get('validation.attributes', [], $locale);
+        }
+
+        $source = Arr::dot((array) $attributes);
+
+        if (isset($customAttributes[$name])) {
+            return $customAttributes[$name];
+        }
+
+        $rules = $validator->getRules();
+        $validatorData = $validator->getData();
+
+        $candidates = [$name];
+        $dottedData = Arr::dot($this->data);
+
+        foreach ($this->implicitAttributes as $unparsed => $parsed) {
+            if (in_array($name, $parsed, true)) {
+                $candidates[] = $unparsed;
+                break;
+            }
+        }
+
+        $contextNames = array_unique(array_merge(
+            $candidates,
+            array_keys($dottedData),
+            array_keys(Arr::dot($validatorData)),
+            array_keys($rules)
+        ));
+
+        foreach ($contextNames as $candidate) {
+            if ($candidate !== $name && ! in_array($name, $this->implicitAttributes[$candidate] ?? [], true)) {
+                continue;
+            }
+
+            if (isset($source[$candidate])) {
+                return $source[$candidate];
+            }
+
+            foreach (array_keys($source) as $sourceKey) {
+                if (str_contains($sourceKey, '*')) {
+                    $pattern = str_replace('\*', '([^.]*)', preg_quote($sourceKey, '#'));
+
+                    if (preg_match('#^'.$pattern.'\z#u', $candidate) === 1) {
+                        return $source[$sourceKey];
+                    }
+                }
+            }
+        }
+    }
+
     /**
